																						"css": "@ {\n\twhite-space: nowrap;\n}@ \nDIV.TitleLevel2\n{\n\tborder-bottom: 1px solid #A0A5A8;\n\tmargin: 10px 0px 10px 0px;\n\tposition: relative;\n\tvertical-align: bottom;\n\twidth: 100%;\n}@ \nDIV.TitleLevel2 H2\n{\n\tpadding-left: 5px;\n\tpadding-top: 3px;\t\n\tbackground-color: #737A7E;\n\tdisplay: inline;\n\tcolor: white;\n\tfont-size: 11px;\n\tfont-weight: bold;\n\tpadding-right: 5px;\n}@ \nDIV.Panel_Tab_Content DIV.TitleLevel2 H2\n{\n\tbackground-color: #456b8c;\n\tcolor: white;\n}@ \nTR.CheckList_ListHeader,@  TR.list_header\n{\n\tbackground-color: #727a7e;\n\tcolor: White;\n\tborder-collapse: collapse;\n}@ \nTD.CheckList_ListHeader\n{\n\tpadding-left: 5px;\n}@ \nTD.list_header_text\n{\n\tborder: 1px solid White;\n\tpadding: 0px 2px 0px 2px;\n\tborder-collapse: collapse;\n}@ \nTD.list_header_text A\n{\n\tcolor: White;\n\ttext-decoration: none;\n}@ \nA.list_header_link\n{\n\tcolor: White;\n\ttext-decoration: none;\n}@ \nA.list_header_link:hover\n{\n\ttext-decoration: underline;\n}@ \nTR.CheckList_ListItem,@  TR.edr-L1\n{\n\tbackground-color: #E8E9EB !important;\n}@ \nTR.edr-L1,@  TR.edr-L2\n{\n\tpadding: 2px !important;\n}@ \nTR.edr-L1 TD A,@  TR.edr-L2 TD A\n{\n\tcolor: #000000;\n\ttext-decoration: none;\n}@ \nTR.edr-L1 TD SPAN.Browsebutton A,@  TR.edr-L2 TD SPAN.Browsebutton A\n{\n\tcolor:white; \n\ttext-decoration:none;\n}@ \nTD.list_text\n{\n\tborder: 1px solid White;\n\tpadding: 0px 2px 0px 2px;\n\theight: 25px;\n}@ \nTD.list_textInteger\n{\n\tborder: 1px solid White;\n\tpadding: 0px 2px 0px 2px;\n\theight: 25px;\n\ttext-align: right;\n}@ \nTD.list_textHidden\n{\n\tdisplay: none;\n}@ \nTR.list_textHidden\n{\n\tdisplay: none;\n\theight: 0px;\n}@ \nTR.CheckList_ListItemAlternate,@  TR.edr-L2\n{\n\tbackground-color: #E8E9EB !important;\n}@  \nTABLE.simulationTableSub{\n\tpadding-bottom: 10px;\n}@ \n",
