																					"options": {
																						"label": "NewConversationMessageWarning__",
																						"htmlContent": "<div class=\"Conversation_Warning_Text\"><span id=\"setMessage\" onclick=\"setMessage(event)\"></span>\n<a class=\"Button FormButton notSelectable Button_Enabled Resized Conversation_Warning_Button\" type=\"button\"><span>OK</span></a>\n</div>\n\n<script>\ndocument.querySelector(\".Conversation_Warning_Button\").addEventListener(\"click\",function()\n{\nwindow.postMessage({eventName: \"onClick\", control: \"NewConversationMessageWarning__\"}, document.location.origin);\n});\n\nfunction setMessage(evt) \n{\nif(evt.warningConversationMessage!= null && evt.warningConversationMessage!=\"\")\n{\ndocument.querySelector(\".Conversation_Warning_Text > span\").textContent = evt.warningConversationMessage;\n}\n}\n</script>\n",
																						"css": "@ .Conversation_Warning_Text\n{\nbackground: #F6B221;\nmargin-bottom: 10px;\nheight: 25px;\ndisplay: flex;\nalign-items: center;\njustify-content: center;\n}@ \n\n.Conversation_Warning_Button\n{\n    padding-left: 4px;\n    padding-right: 4px;\n    margin: 7px !important;\n    margin-bottom: 7px !important;\n    height: 20px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}@ \n\n.Conversation_Warning_Button > span\n{\n    height: 25px;\n    padding : inherit;\n    font-size: 11px;\n}@ \n",
